CREATE VIEW [dbo].[NU_VGetDonorDetails] -- SELECT * FROM NU_VGetDonorDetails
AS
SELECT		B.Donorkey, DonorName, Amount , EventGroupName , A.EventGroupKey
			,DonorPlace, IsUdyavarParish

FROm		NU_DonorAmountDetails A
INNER JOIN	NU_DonorList B ON A.DonorKey = B.Donorkey 
INNER JOIN	NU_EventGroupMaster C ON A.EventGroupKey = C.EventGroupKey 
GO
/****** Object:  View [dbo].[NU_VGetEventDetails]    Script Date: 17-09-2026 00:14:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[NU_VGetEventDetails]
AS
SELECT		ED.EventKey, ED.EventCatKey,CM.EventCatName,ED.LangKey , LM.LangName, EGM.EventGroupKey, EGM.EventGroupName, EventName,EventDate, TeamName 
FROM		NU_EventDetails ED
INNER JOIN	NU_EventCategoryMaster CM ON ED.EventCatKey = CM.EventCatKey 
INNER JOIN	NU_LanguageMaster LM ON ED.LangKey = LM.LangKey 
INNER JOIN	NU_EventGroupMaster EGM ON ED.EventGroupKey = EGM.EventGroupKey
GO
