CREATE PROCEDURE	[dbo].[NU_GetDonorDetails]
(
	@UserKey	INT = 0,
	--@JsonText	NVARCHAR(MAX) = '{"FilterKey":1,"FilterSelectionData":[{"FilterSelectionKey":3},{"FilterSelectionKey":2}]}'
	@JsonText	NVARCHAR(MAX) = '{"FilterKey":0}'
)
AS

DECLARE @FilterKey	INT = 0
 
SELECT  @FilterKey = FilterKey
from OpenJson(@JsonText, '$')
	With (
		FilterKey			int				'$.FilterKey'
		)

		SET @FilterKey = ISNULL(@FilterKey,0)

		-- SELECT @FilterKey

CREATE TABLE #FilterData
(
	FilterSelectionKey INT
)


INSERT INTO #FilterData
SELECT  *
from OpenJson(@JsonText, '$.FilterSelectionData')
	With (
			FilterSelectionKey			int				'$.FilterSelectionKey'
		)

		--SELECT @FilterKey

CREATE TABLE #DonorKey
(
	DonorKey		INT
)

BEGIN
	
	DECLARE		@JSONResult NVARCHAR(MAX)

	SELECT		DD.DonorName, DD.DonorPlace
				,   DD1.Donorkey
				,CASE WHEN @UserKey = 1 THEN 0 ELSE  dd1.Amount END AS Amount, '9880814814'AS MobileNo
				,CASE WHEN @UserKey = 1 THEN 0 ELSE  dd1.CNT END AS CNT
	INTO		#DonorList
	FROM		NU_DonorList DD
	LEFT JOIN	(SELECT Donorkey,SUM(Amount)Amount, COUNT(*) CNT   FROM NU_VGetDonorDetails 
				GROUP BY Donorkey) DD1 ON DD.Donorkey = DD1.Donorkey
				--FOR JSON PATH 
	
	IF(@FilterKey = 1)
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
			LEFT JOIN	#FilterData FD ON DD.EventGroupKey = FD.FilterSelectionKey
			WHERE		fd.FilterSelectionKey IS NULL
			
		END
	ELSE IF (@FilterKey = 2)
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
			INNER JOIN	#FilterData FD ON DD.EventGroupKey = FD.FilterSelectionKey
		END
	ELSE IF (@FilterKey = 3)
		BEGIN
			INSERT INTO #DonorKey
			SELECT Donorkey FROM (
					SELECT		Donorkey, SUM(Amount) TOTAmount
								FROM		NU_VGetDonorDetails DD			
								GROUP BY Donorkey ) A
					WHERE TOTAmount >= 10000
		END
	ELSE 
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
		END
	
	--SELECT DL.* FROM #DonorList DL
	--					INNER JOIN #DonorKey DK ON DL.Donorkey = DK.DonorKey

		SET @JSONResult = (SELECT DL.* FROM #DonorList DL
						INNER JOIN #DonorKey DK ON DL.Donorkey = DK.DonorKey FOR JSON PATH)
			


		SELECT @JSONResult AS JSONResult


END
GO
