CREATE PROCEDURE	[dbo].[NU_GetDonorDetails_Delete]
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"FilterKey":1,"FilterSelectionData":[{"FilterSelectionKey":3},{"FilterSelectionKey":2}]}'
	--@JsonText	NVARCHAR(MAX) = '{"FilterKey":2}'
)
AS

DECLARE @FilterKey	INT = 0
 
SELECT  @FilterKey = FilterKey
from OpenJson(@JsonText, '$')
	With (
		FilterKey			int				'$.FilterKey'
		)

		SET @FilterKey = ISNULL(@FilterKey,0)

		-- SELECT @FilterKey

CREATE TABLE #FilterData
(
	FilterSelectionKey INT
)


INSERT INTO #FilterData
SELECT  *
from OpenJson(@JsonText, '$.FilterSelectionData')
	With (
			FilterSelectionKey			int				'$.FilterSelectionKey'
		)

		SELECT * FROM #FilterData

CREATE TABLE #DonorKey
(
	DonorKey		INT
)

BEGIN
	
	DECLARE		@JSONResult NVARCHAR(MAX)

	SELECT		DD.DonorName, DD.DonorPlace,   DD1.*
	INTO		#DonorList
	FROM		NU_DonorList DD
	LEFT JOIN	(SELECT Donorkey,SUM(Amount)Amount, COUNT(*) CNT   FROM NU_VGetDonorDetails 
				GROUP BY Donorkey) DD1 ON DD.Donorkey = DD1.Donorkey
				--FOR JSON PATH 
	
	IF(@FilterKey = 1)
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
			LEFT JOIN	#FilterData FD ON DD.EventGroupKey = FD.FilterSelectionKey
			WHERE		fd.FilterSelectionKey IS NULL
			
		END
	ELSE IF (@FilterKey = 2)
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
			INNER JOIN	#FilterData FD ON DD.EventGroupKey = FD.FilterSelectionKey
		END
	ELSE IF (@FilterKey = 3)
		BEGIN
			INSERT INTO #DonorKey
			SELECT Donorkey FROM (
					SELECT		Donorkey, SUM(Amount) TOTAmount
								FROM		NU_VGetDonorDetails DD			
								GROUP BY Donorkey ) A
					WHERE TOTAmount >= 10000
		END
	ELSE 
		BEGIN
			INSERT INTO #DonorKey
			SELECT		DISTINCT DD.Donorkey
			FROM		NU_VGetDonorDetails DD
		END
	
	SELECT DL.* FROM #DonorList DL
						INNER JOIN #DonorKey DK ON DL.Donorkey = DK.DonorKey

		SET @JSONResult = (SELECT DL.* FROM #DonorList DL
						INNER JOIN #DonorKey DK ON DL.Donorkey = DK.DonorKey FOR JSON PATH)
			


		SELECT @JSONResult AS JSONResult


END
GO
/****** Object:  StoredProcedure [dbo].[NU_GetDonorDonationAnalysis]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[NU_GetDonorDonationAnalysis]
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"UserID":"roshan","PIN":"1234"}'
)
AS
BEGIN
SELECT * into #Data 
FROM
(
SELECT Donorkey,DonorName,Amount,EventGroupName,DD.EventGroupKey,DonorPlace, EventYear  FROM NU_VGetDonorDetails DD
INNER JOIN (SELECT DISTINCT EventGroupKey, YEAR(EventDate) EventYear
FROM NU_VGetEventDetails ) ED ON DD.EventGroupKey = ED.EventGroupKey
UNION ALL
SELECT DL.Donorkey,DonorName,Amount,'Not Donated',EventGroupKey,DonorPlace,0 FROM NU_DonorList DL
LEFT JOIN NU_DonorAmountDetails AD ON DL.Donorkey = AD.DonorKey
WHERE AD.DonorKey IS NULL
) A

DECLARE @JSONResult NVARCHAR(MAX) = (
SELECT   
    d.DonorName,
    d.DonorPlace,
    MAX(d.EventYear) AS LastDonationYear,
    YEAR(GETDATE()) - MAX(d.EventYear) AS YearsSinceLastDonation,
    COUNT(*) AS TotalPayments,                  -- total times donated
    SUM(d.Amount) AS TotalAmount,               -- total donated
    AVG(d.Amount) AS AvgAmountPaid,             -- average donation
    (
        SELECT TOP 1 d2.Amount
        FROM #Data d2
        WHERE d2.DonorName = d.DonorName
        ORDER BY d2.EventGroupKey DESC
    ) AS LastAmountPaid,                        -- last donation amount
    (
        SELECT TOP 1 d2.EventGroupName
        FROM #Data d2
        WHERE d2.DonorName = d.DonorName
        ORDER BY d2.EventGroupKey DESC
    ) AS LastEventName ,                         -- last event name
	(
            SELECT 
                DA.EventGroupName AS EventName, 
                DA.Amount AS Amount, 
                DA.EventYear AS EventYear
            FROM #Data DA 
            WHERE DA.DonorName = d.DonorName
            FOR JSON PATH
        ) AS DonorDetails
FROM #Data d
GROUP BY d.DonorName, d.DonorPlace
HAVING YEAR(GETDATE()) - MAX(d.EventYear) >= 0
FOR JSON PATH, ROOT('Donors'))

SELECT @JSONResult AS JsonResult

END
GO
