CREATE PROCEDURE	[dbo].[NU_GetDonorEventwiseAmount] -- NU_GetDonorEventwiseAmount 11 ,''
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"DonorKey": 7}'
)
AS

DECLARE @DonorKey	INT = 0

SELECT  @DonorKey = DonorKey
from OpenJson(@JsonText, '$')
	With (
		DonorKey			int				'$.DonorKey'
		)

SELECT		GM.EventGroupName, DD.Amount
			, CAST(CASE WHEN DD.EventGroupKey IS NULL THEN 0 ELSE 1 END AS BIT) IsDonated 
FROM		NU_EventGroupMaster GM
LEFT JOIN	NU_VGetDonorDetails DD ON GM.eventgroupkey = DD.EventGroupKey AND Donorkey = @DonorKey
FOR JSON PATH
GO
