CREATE PROCEDURE [dbo].[NU_GetEventGroupExpenses] -- NU_GetEventGroupExpenses 23
(
	@EventGroupKey	INT
)

AS
BEGIN
	SELECT 
	JSON_QUERY(
	(
		SELECT * FROM (
			SELECT 'Donations' AS Receipts,
				   SUM(ISNULL(CashAmount,0) + ISNULL(BankAmount,0)) AS Amount,
				   SUM(CASE WHEN ISNULL(ReceiptBook_Rno,0)> 0 THEN ISNULL(CashAmount,0) ELSE 0 END 
				   + CASE WHEN ISNULL(ReceiptBook_Rno,0)> 0 THEN ISNULL(BankAmount,0) ELSE 0 END) AS ReceiptAmount
			FROM NU_Receipts 
			WHERE EventGroupKey = @EventGroupKey

			UNION ALL

			SELECT 'Box Collection',
				   SUM(Amount),SUM(Amount)
			FROM NU_BoxCollections
			WHERE EventGroupKey = @EventGroupKey

			UNION ALL

			SELECT 'Govt Grants',
				   SUM(Amount),0
			FROM NU_GovtGrants 
			WHERE EventGroupKey = @EventGroupKey
		) A
		FOR JSON PATH
	)
	) AS Receipts,

	JSON_QUERY(
	(
		SELECT ExpenseDetails, EE.Amount, EM.Amount AS VoucherAmount  FROM NU_EventExpenses EE
		LEFT JOIN (SELECT EventExpenseKey, SUM(Amount) Amount FROM NU_PaymentExpenseMapping WHERE ISNULL(DeletedFlag,0) = 0
GROUP BY EventExpenseKey ) EM ON EE.EventExpenseKey = EM.EventExpenseKey
		WHERE EventGroupKey = @EventGroupKey AND ISNULL(EE.DeletedFlag,0) = 0
		FOR JSON PATH
	)
	) AS Payments

FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;
END
