CREATE PROCEDURE	[dbo].[NU_GetFilterSelectionKeys] -- NU_GetDonorEventwiseAmount 11 ,''
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"FilterKey": 2}'
	-- @JsonText	NVARCHAR(MAX) = '{"FilterKey": 2}'
)
AS

BEGIN
	DECLARE @FilterKey	INT = 0, @JsonResult NVARCHAR(MAX)

	SELECT  @FilterKey = FilterKey
	from OpenJson(@JsonText, '$')
		With (
			FilterKey INT	'$.FilterKey'
			)

	CREATE TABLE #FilterData
	(
		FilterSelectionKey	INT,
		FilterSelectionData	VARCHAR(100)
	)

	IF(@FilterKey IN (1,2))
		BEGIN
			INSERT INTO #FilterData
			SELECT EventGroupKey, EventGroupName FROM NU_EventGroupMaster
		END
	ELSE IF (@FilterKey IN (3))
		BEGIN
			INSERT INTO #FilterData
			SELECT EventYear YearKey, EventYear FROM (
			SELECT DISTINCT YEAR(EventDate) as EventYear FROM NU_EventDetails )A
			ORDER BY EventYear
		END

	SET @JsonResult = (SELECT @FilterKey AS FilterKey , FilterSelectionData =  (SELECT * FROM #FilterData FOR JSON PATH)
	FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)

	-- SET @JsonResult = '[{"FilterKey":1,"FilterDetails":"Not Contributed for","IsSubFilter":true},{"FilterKey":2,"FilterDetails":"Contributed for","IsSubFilter":true},{"FilterKey":3,"FilterDetails":"Not Contributed in the year","IsSubFilter":true},{"FilterKey":4,"FilterDetails":"Average Contribution is more than 10000","IsSubFilter":false}]'

	SELECT @JsonResult AS JsonResult
END
