CREATE PROCEDURE	[dbo].[NU_InsertUpdateDonorDetails]
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"ProcName":"NU_InsertUpdateDonorDetails","UserKey":1,"JsonText":"{\"DonorName\":\"ABCD\",\"DonorPlace\":\"sssss\",\"Addr1\":\"aaa\",\"Addr2\":\"bbb\",\"Addr3\":\"ccc\",\"City\":\"ddd\",\"State\":\"sssss\",\"Phone\":\"eee\",\"IsUdyavarParish\":true}"}'
)
AS

INSERT INTO DebugData (Value1, CreatedDate)
SELECT @JsonText, GETDATE()


BEGIN
DECLARE @DonorKey INT , @DonorName	VARCHAR(50), @DonorPlace VARCHAR(50), @JSONResult NVARCHAR(MAX),
		@Addr1 varchar(100), @Addr2 varchar(100), @Addr3 varchar(100), @City varchar(100)
		, @State varchar(100), @Phone varchar(100), @IsUdyavaraParish BIT
 
SELECT  @DonorKey = DonorKey,@DonorName = DonorName, @DonorPlace = DonorPlace, @Addr1 = Add1, @Addr2 = Add2,
		@Addr3 = Add3 , @City = City , @State = DState, @Phone = Phone
		, @IsUdyavaraParish = IsUdyavaraParish
from OpenJson(@JsonText, '$')
	With (
			DonorKey			INT				'$.DonorKey',
			DonorName			VARCHAR(50)		'$.DonorName',
			DonorPlace			VARCHAR(50)		'$.DonorPlace',
			Add1				VARCHAR(50)		'$.Addr1',
			Add2				VARCHAR(50)		'$.Addr2',
			Add3				VARCHAR(50)		'$.Addr3',
			City				VARCHAR(50)		'$.City',
			DState				VARCHAR(50)		'$.State',
			Phone				VARCHAR(50)		'$.Phone',
			IsUdyavaraParish	BIT				'$.IsUdyavarParish'
		)

DECLARE @IsExists BIT = 0, @ReturnMessage VARCHAR(1000) = '', @IsSuccess BIT = 0
	
SELECT		@IsExists = CASE WHEN COUNT(*) = 0 THEN 0 ELSE 1 END
FROM		NU_DonorList
WHERE		REPLACE(RTRIM(LTRIM(DonorName)),' ','') = REPLACE(RTRIM(LTRIM(@DonorName)),' ','')

SET @DonorKey = ISNULL(@DonorKey,0)

IF(@IsExists = 1 AND @DonorKey = 0)
	BEGIN
		SET @ReturnMessage = 'Donor Already Exists'
		
	END
ELSE
	BEGIN
		SET @ReturnMessage = 'Saved Successfully'
		SET @IsSuccess = 1
	END

IF(@IsSuccess = 1)
	IF(@DonorKey = 0)
		BEGIN
			INSERT INTO NU_DonorList (DonorName,DonorPlace,Addr1,Addr2,Addr3,City,DState,Phone,IsUdyavarParish)
			SELECT @DonorName,@DonorPlace,@Addr1,@Addr2, @Addr3, @City, @State,@Phone,@IsUdyavaraParish
		END
	ELSE
		BEGIN
			UPDATE NU_DonorList
			SET DonorName = @DonorName, DonorPlace = @DonorPlace, Addr1 = @Addr1,Addr2 = @Addr2
			,Addr3 = @Addr3, City = @City, DState = @State, Phone = @Phone, IsUdyavarParish = @IsUdyavaraParish
			WHERE Donorkey = @DonorKey
		END

SET @JSONResult =			
(SELECT CAST(@IsSuccess AS BIT) IsSuccess, @ReturnMessage AS ReturnMessage FOR JSON PATH) 

SELECT @JSONResult AS JsonResult


END
