/****** Object:  StoredProcedure [dbo].[NU_sp_Dashboard_GetSummary]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[NU_sp_Dashboard_GetSummary]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Calculate Summary Totals
    DECLARE @CashInHand DECIMAL(18,2) = 0;
    DECLARE @BankBalance DECIMAL(18,2) = 0;
    DECLARE @ActiveEvents INT = 0;

    -- Basic estimation of Cash in Hand (total cash receipts - total cash payments)
    DECLARE @TotalCashReceipts DECIMAL(18,2) = ISNULL((SELECT SUM(CashAmount) FROM NU_Receipts WHERE PaymentMode = 'Cash' AND DeletedFlag = 0), 0);
    DECLARE @TotalCashPayments DECIMAL(18,2) = ISNULL((SELECT SUM(DebitAmount) FROM NU_Payments WHERE PaymentMode = 'Cash' AND DeletedFlag = 0), 0);
    SET @CashInHand = @TotalCashReceipts - @TotalCashPayments;

    -- Basic estimation of Bank Balance (total bank receipts - total bank payments)
    DECLARE @TotalBankReceipts DECIMAL(18,2) = ISNULL((SELECT SUM(BankAmount) FROM NU_Receipts WHERE PaymentMode <> 'Cash' AND DeletedFlag = 0), 0);
    DECLARE @TotalBankPayments DECIMAL(18,2) = ISNULL((SELECT SUM(DebitAmount) FROM NU_Payments WHERE PaymentMode <> 'Cash' AND DeletedFlag = 0), 0);
    SET @BankBalance = @TotalBankReceipts - @TotalBankPayments;

    -- Active Events
    SET @ActiveEvents = ISNULL((SELECT COUNT(*) FROM NU_EventGroups WHERE IsActive = 1 AND Status = 'Active'), (SELECT COUNT(*) FROM NU_EventGroups WHERE IsActive = 1));

    -- Return Totals
    SELECT @CashInHand AS CashInHand, @BankBalance AS BankBalance, @ActiveEvents AS ActiveEvents;

    -- 2. Calculate Recent Activities
    -- Combine top receipts and payments
    SELECT TOP 5 
        Action, Details, Time, Icon, Color, ActivityDate
    FROM
    (
        SELECT 
            'Receipt Generated' AS Action,
            'â‚¹' + CAST((ISNULL(CashAmount, 0) + ISNULL(BankAmount, 0)) AS VARCHAR) + ' from ' + ISNULL(CAST(DonorId AS VARCHAR), 'Donor') AS Details,
            '' AS Time,
            'add_circle' AS Icon,
            'green' AS Color,
            ISNULL(ReceivedDate, ReceiptDate) AS ActivityDate
        FROM NU_Receipts
        WHERE DeletedFlag = 0

        UNION ALL

        SELECT 
            'Payment Voucher' AS Action,
            'â‚¹' + CAST(DebitAmount AS VARCHAR) + ' for ' + ISNULL(Description, 'Expense') AS Details,
            '' AS Time,
            'remove_circle' AS Icon,
            'red' AS Color,
            PaymentDate AS ActivityDate
        FROM NU_Payments
        WHERE DeletedFlag = 0
    ) AS CombinedActivities
    ORDER BY ActivityDate DESC;
    
END

