-- Stored Procedures for Donors

CREATE   PROCEDURE [dbo].[NU_sp_Donor_Insert]
    @DonorName NVARCHAR(150),
    @MobileNumber NVARCHAR(20),
    @DPlace NVARCHAR(100),
    @DAddr1 NVARCHAR(200),
    @DAddr2 NVARCHAR(200),
    @DAddr3 NVARCHAR(200),
    @DCity NVARCHAR(100),
    @DState NVARCHAR(100),
    @IsUdyavarParish BIT,
    @PANNumber NVARCHAR(20),
    @Email NVARCHAR(100),
    @Remarks NVARCHAR(MAX),
    @CreatedBy INT
