CREATE   PROCEDURE [dbo].[NU_sp_Payment_Delete]
    @PaymentId INT,
    @ModifiedBy INT
AS
BEGIN
    UPDATE NU_Payments
    SET DeletedFlag = 1,
        ModifiedBy = @ModifiedBy,
        ModifiedDate = GETDATE()
    WHERE PaymentId = @PaymentId;

    -- Unsettle expense links if this was a reimbursement payment
    UPDATE NU_PaymentExpenseLinks
    SET IsSettled = 0,
        SettledDate = NULL,
        PaymentId = NULL,
        ModifiedBy = @ModifiedBy,
        ModifiedDate = GETDATE()
    WHERE PaymentId = @PaymentId;
END;

