CREATE   PROCEDURE [dbo].[NU_sp_Reimbursement_Update]
    @ReimbursementId INT,
    @ReimbursementDate DATE,
    @UserId INT,
    @EventGroupId INT,
    @ExpenseCategoryId INT,
    @Amount DECIMAL(18,2),
    @Description NVARCHAR(MAX),
    @BillAvailable BIT,
    @BillNumber NVARCHAR(100),
    @BillDate DATE,
    @AttachmentPath NVARCHAR(MAX),
    @Status NVARCHAR(50),
    @ModifiedBy INT
AS
BEGIN
    UPDATE NU_Reimbursements
    SET ReimbursementDate = @ReimbursementDate,
        UserId = @UserId,
        EventGroupId = @EventGroupId,
        ExpenseCategoryId = @ExpenseCategoryId,
        Amount = @Amount,
        Description = @Description,
        BillAvailable = @BillAvailable,
        BillNumber = @BillNumber,
        BillDate = @BillDate,
        AttachmentPath = @AttachmentPath,
        Status = @Status,
        ModifiedBy = @ModifiedBy,
        ModifiedDate = GETDATE()
    WHERE ReimbursementId = @ReimbursementId;
END;

