/****** Object:  StoredProcedure [dbo].[NU_sp_Report_EventPNL]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

-- 4. Event-wise Income & Expense (P&L)
CREATE   PROCEDURE [dbo].[NU_sp_Report_EventPNL]
    @EventId INT
AS
BEGIN
    DECLARE @TotalIncome DECIMAL(18,2);
    DECLARE @TotalExpense DECIMAL(18,2);

    SELECT @TotalIncome = ISNULL(SUM(CashAmount + BankAmount), 0)
    FROM Receipts WHERE EventId = @EventId AND DeletedFlag = 0;

    SELECT @TotalExpense = ISNULL(SUM(DebitAmount), 0)
    FROM Payments WHERE EventId = @EventId AND DeletedFlag = 0;

    SELECT 
        e.EventName,
        @TotalIncome AS TotalIncome,
        @TotalExpense AS TotalExpense,
        (@TotalIncome - @TotalExpense) AS ProfitLoss
    FROM Events e
    WHERE e.EventId = @EventId;
END;

