/****** Object:  StoredProcedure [dbo].[NU_sp_Report_GetVoucherReport]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[NU_sp_Report_GetVoucherReport] -- NU_sp_Report_GetVoucherReport 0,'2025-26',0,''
(
    @EventGroupKey INT = 0,
    @FinancialYear VARCHAR(7) = '',
    @VendorKey INT = 0,
    @VoucherNo VARCHAR(50) = ''
)
AS
BEGIN

    SET NOCOUNT ON;

    ------------------------------------------------------------
    -- Convert "All" values to NULL
    ------------------------------------------------------------

    SET @EventGroupKey = NULLIF(@EventGroupKey, 0);
    SET @VendorKey     = NULLIF(@VendorKey, 0);
    SET @VoucherNo     = NULLIF(@VoucherNo, '');
    SET @FinancialYear = NULLIF(@FinancialYear, '');

    ------------------------------------------------------------
    -- Financial Year Date Range
    --
    -- Example:
    -- 2025-26 = 01-Apr-2025 to 31-Mar-2026
    -- 2026-27 = 01-Apr-2026 to 31-Mar-2027
    ------------------------------------------------------------

    DECLARE @FYStartDate DATE;
    DECLARE @FYEndDate DATE;

    IF @FinancialYear IS NOT NULL
    BEGIN

        SET @FYStartDate =
            DATEFROMPARTS
            (
                CAST(LEFT(@FinancialYear, 4) AS INT),
                4,
                1
            );

        SET @FYEndDate =
            DATEADD(YEAR, 1, @FYStartDate);

    END;

    WITH PaymentDetails AS
    (
        
 SELECT       P.VoucherNumber,P.PaymentID,P.DebitAmount,P.PaymentType,ISNULL(EL.Amount,P.DebitAmount) AS Amount,
                    ISNULL(EL.BillNo,P.BillNumber) AS BillNo,CAST(ISNULL(EL.BillDate,P.BillDate) AS VARCHAR(20)) AS BillDate,
                    V.VendorName,ISNULL(ISNULL(EL.IsVoucherOnly,P.IsVoucherOnly),0) AS IsVoucherOnly,
                    P.PaymentMode,P.VoucherDate,P.PaymentDate,CM.CategoryName,U.MemberName
                    -- ,ISNULL(CAST(EL.ExpenseId AS VARCHAR), P.VoucherNumber)  AS ExpenseID
                    , UPPER(LEFT(REPLACE(P.PaymentType,'-',''),3)) + ' - ' +  RIGHT('0000' +  CAST(ISNULL(EL.ExpenseId,P.PaymentId) AS VARCHAR),4) AS ExpenseID
                    ,CASE WHEN P.ExpenseCategoryId = 3 THEN 'Bank Transfer Charges for the Voucher : ' +  PY.VoucherNumber ELSE P.Description END  AS Narration,
                    EG.EventGroupName,
                    '' AS Remarks,ROW_NUMBER() OVER (PARTITION BY PY.PaymentID ORDER BY EL.Amount,EL.BillNo,V.VendorName) AS RowNo,
                    COUNT(*) OVER (PARTITION BY P.PaymentID) AS TotalRows
                    ,El.Remarks AS LinkRemarks
        FROM        NU_Payments P
        LEFT JOIN   NU_PaymentExpenseLinks EL ON P.PaymentID = EL.PaymentId AND ISNULL (EL.DeletedFlag,0) = 0
        LEFT JOIN   NU_Vendors V ON V.VendorId =ISNULL(EL.VendorKey,P.VendorId)
        LEFT JOIN   NU_Categories CM ON CM.CategoryId = P.ExpenseCategoryId OR EL.ExpenseCategoryKey = CM.CategoryId 
        LEFT JOIN   NU_MemberDetails U ON P.MemberId = U.MemberKey
        LEFT JOIN   NU_EventGroups EG ON P.EventGroupKey = EG.EventGroupId OR EL.EventGroupKey = EG.EventGroupId 
        LEFT JOIN   (        SELECT P.PaymentId ,  T.VoucherNumber FROM NU_Payments P
                    INNER JOIN NU_Payments T ON P.RelatedPaymentID = T.PaymentId ) PY ON PY.PaymentId = P.PaymentId
        WHERE       ISNULL(P.DeletedFlag,0) = 0 AND ISNULL(EL.DeletedFlag,0) = 0
                    AND (@EventGroupKey IS NULL OR ISNULL(P.EventGroupKey,EL.EventGroupKey) = @EventGroupKey)
                    AND (@FinancialYear IS NULL OR (P.VoucherDate >= @FYStartDate AND P.VoucherDate < @FYEndDate ))
                    AND (@VendorKey IS NULL OR ISNULL(EL.VendorKey,P.VendorId) = @VendorKey )
                    AND (@VoucherNo IS NULL OR P.VoucherNumber = @VoucherNo))


        SELECT     P.VoucherNumber,P.PaymentID,P.DebitAmount,REPLACE(P.PaymentType,'Multiple Payments','Normal') AS VoucherType
                    ,P.PaymentMode,P.Narration,P.Remarks,
                    CASE WHEN P.PaymentType = 'Re-Imbursement' THEN P.MemberName ELSE P.VendorName END AS PayTo,
                    CASE WHEN P.PaymentMode = 'Cash' THEN 'Cash' ELSE 'Badagabettu Credit Co-Operative Society' END AS AccountName,
                    P.VoucherDate,P.PaymentDate,
                    JSON_QUERY
                    (
                        (   SELECT      D.RowNo,D.Amount,D.BillNo,D.BillDate,D.VendorName AS Party,
                                        D.IsVoucherOnly
                                        ,D.CategoryName 
                                        ,D.ExpenseID, EventGroupName   
                                        +  CASE WHEN ISNULL(LinkRemarks,'') = '' THEN '' ELSE  CHAR(10) + LinkRemarks END As ExpDesc
                            FROM        PaymentDetails D
                            WHERE       D.PaymentID = P.PaymentID
                            ORDER BY    D.RowNo
                            FOR JSON PATH
                        )
                    ) AS PaymentAccDetails
        FROM        PaymentDetails P
        -- WHERE       P.VoucherNumber LIKE '2025/26-%' AND CAST(REPLACE(P.VoucherNumber,'2025/26-','') AS INT) > 130
        GROUP BY    P.VoucherNumber,P.PaymentID,P.DebitAmount,P.PaymentType,P.PaymentMode,P.Narration,P.Remarks,
                    CASE WHEN P.PaymentType = 'Re-Imbursement' THEN P.MemberName ELSE P.VendorName END,
                    P.VoucherDate,P.PaymentDate
        ORDER BY    CAST(REPLACE(P.VoucherNumber,'2025/26-','') AS INT)

END
GO
/****** Object:  StoredProcedure [dbo].[NU_sp_Report_IncomeExpenditure]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

-- 6. Income and Expenditure Summary
CREATE   PROCEDURE [dbo].[NU_sp_Report_IncomeExpenditure]
    @StartDate DATE,
    @EndDate DATE
AS
BEGIN
    SELECT 
        'Income' AS Type,
        eg.EventGroupName AS ItemName,
        SUM(r.CashAmount + r.BankAmount) AS Amount
    FROM NU_Receipts r
    LEFT JOIN NU_EventGroups eg ON r.EventGroupKey = eg.EventGroupId
    WHERE r.ReceiptDate BETWEEN @StartDate AND @EndDate AND r.DeletedFlag = 0
    GROUP BY eg.EventGroupName

    UNION ALL

    -- Exclude Reimbursements to avoid double counting
    SELECT 
        'Expenditure' AS Type,
        c.CategoryName AS ItemName,
        SUM(p.DebitAmount) AS Amount
    FROM NU_Payments p
    LEFT JOIN NU_Categories c ON p.ExpenseCategoryId = c.CategoryId
    WHERE p.PaymentDate BETWEEN @StartDate AND @EndDate AND p.DeletedFlag = 0
    AND p.IsReimbursement = 0
    GROUP BY c.CategoryName

    UNION ALL

    -- Include settled Payment Expense Links
    SELECT 
        'Expenditure' AS Type,
        c.CategoryName AS ItemName,
        SUM(el.Amount) AS Amount
    FROM NU_PaymentExpenseLinks el
    LEFT JOIN NU_Categories c ON el.ExpenseCategoryKey = c.CategoryId
    WHERE el.IsSettled = 1 AND el.SettledDate BETWEEN @StartDate AND @EndDate AND el.DeletedFlag = 0
    GROUP BY c.CategoryName;
END;

