/****** Object:  StoredProcedure [dbo].[NU_sp_Report_PaymentRegister]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

-- 2. Payment Register (Between Dates)
CREATE   PROCEDURE [dbo].[NU_sp_Report_PaymentRegister]
    @StartDate DATETIME,
    @EndDate DATETIME
AS
BEGIN
    SELECT 
        p.PaymentId,
        p.VoucherNumber,
        p.PaymentDate,
        CASE WHEN p.IsReimbursement = 1 THEN m.MemberName ELSE v.VendorName END AS VendorName,
        e.EventName,
        c.CategoryName,
        p.PaymentMode,
        p.DebitAmount,
        p.Description
    FROM NU_Payments p
    LEFT JOIN NU_Vendors v ON p.VendorId = v.VendorId
    LEFT JOIN NU_MemberDetails m ON p.MemberId = m.MemberKey
    LEFT JOIN NU_EventDetails e ON p.EventKey = e.EventKey
    LEFT JOIN NU_Categories c ON p.ExpenseCategoryId = c.CategoryId
    WHERE p.PaymentDate BETWEEN @StartDate AND @EndDate
    AND p.DeletedFlag = 0
    ORDER BY p.PaymentDate DESC;
END;

