-- 1. Receipt Register (Between Dates)
CREATE   PROCEDURE [dbo].[NU_sp_Report_ReceiptRegister]
    @StartDate DATETIME,
    @EndDate DATETIME
AS
BEGIN
    SELECT 
        r.ReceiptId,
        r.ReceiptNumber,
        r.ReceiptDate,
        r.ReceivedDate,
        r.ReceiptBook_Rno,
        d.DonorName,
        eg.EventGroupName,
        r.PaymentMode,
        r.CashAmount,
        r.BankAmount,
        r.ReferenceNumber,
        r.Description
    FROM NU_Receipts r
    LEFT JOIN NU_Donors d ON r.DonorId = d.DonorId
    LEFT JOIN NU_EventGroups eg ON r.EventGroupKey = eg.EventGroupId
    WHERE r.ReceiptDate BETWEEN @StartDate AND @EndDate
    AND r.DeletedFlag = 0
    ORDER BY r.ReceiptDate DESC;
END;

