/****** Object:  StoredProcedure [dbo].[NU_sp_Report_ReceiptsPayments]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[NU_sp_Report_ReceiptsPayments]
    @FinancialYear NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    -- Calculate Start and End Dates based on Financial Year (e.g., '2025-26')
    DECLARE @StartYear INT = CAST(SUBSTRING(@FinancialYear, 1, 4) AS INT);
    DECLARE @StartDate DATE = CAST(CAST(@StartYear AS VARCHAR) + '-04-01' AS DATE);
    DECLARE @EndDate DATE = CAST(CAST(@StartYear + 1 AS VARCHAR) + '-03-31' AS DATE);

    -- Dynamic Opening Balance Calculation
    DECLARE @CalculatedOpeningBalance DECIMAL(18,2) = 0;

    -- a. Sum of all initial Opening Balances (excluding FD if any)
    DECLARE @BaseOB DECIMAL(18,2) = 0;
    SELECT @BaseOB = ISNULL(SUM(OpeningAmount), 0)
    FROM NU_OpeningBalances
    WHERE DeletedFlag = 0 AND FinancialYear <= @FinancialYear; -- Assuming all entered OBs apply

    -- b. Receipts before StartDate
    DECLARE @PastReceipts DECIMAL(18,2) = 0;
    SELECT @PastReceipts = 
        ISNULL((SELECT SUM(ISNULL(CashAmount, 0) + ISNULL(BankAmount, 0)) FROM NU_Receipts WHERE DeletedFlag = 0 AND ReceiptDate < @StartDate), 0) +
        ISNULL((SELECT SUM(Amount) FROM NU_BoxCollections WHERE DeletedFlag = 0 AND ConsiderForAudit = 1 AND CollectionDate < @StartDate), 0) +
        ISNULL((SELECT SUM(Amount) FROM NU_GovtGrants WHERE DeletedFlag = 0 AND ConsiderForAudit = 1 AND GrantDate < @StartDate), 0);

    -- c. Payments before StartDate
    DECLARE @PastPayments DECIMAL(18,2) = 0;
    SELECT @PastPayments = ISNULL((SELECT SUM(DebitAmount) FROM NU_Payments WHERE DeletedFlag = 0 AND PaymentDate < @StartDate), 0);

    -- d. Bank Transfers to/from FD before StartDate
    -- Transfer to FD (Outflow from Cash/Bank)
    DECLARE @PastFDTransfersOut DECIMAL(18,2) = 0;
    SELECT @PastFDTransfersOut = ISNULL(SUM(Amount), 0)
    FROM NU_BankTransfers
    WHERE DeletedFlag = 0 AND TransferDate < @StartDate
      AND (FromAccountType IN ('Cash', 'Bank') AND ToAccountType = 'Fixed Deposit');

    -- Transfer from FD (Inflow to Cash/Bank)
    DECLARE @PastFDTransfersIn DECIMAL(18,2) = 0;
    SELECT @PastFDTransfersIn = ISNULL(SUM(Amount), 0)
    FROM NU_BankTransfers
    WHERE DeletedFlag = 0 AND TransferDate < @StartDate
      AND (FromAccountType = 'Fixed Deposit' AND ToAccountType IN ('Cash', 'Bank'));

    SET @CalculatedOpeningBalance = @BaseOB + @PastReceipts - @PastPayments - @PastFDTransfersOut + @PastFDTransfersIn;

    -- 1. RECEIPTS
    -- Create temporary table to hold receipts
    CREATE TABLE #Receipts (
        Description NVARCHAR(100),
        Amount DECIMAL(18,2),
        DisplayOrder INT
    );

    -- Opening Balance
    INSERT INTO #Receipts (Description, Amount, DisplayOrder)
    VALUES ('Opening Balance', @CalculatedOpeningBalance, 1);

    -- Donations (NU_Receipts)
    INSERT INTO #Receipts (Description, Amount, DisplayOrder)
    SELECT 'Donations', ISNULL(SUM(ISNULL(CashAmount, 0) + ISNULL(BankAmount, 0)), 0), 2
    FROM NU_Receipts
    WHERE ReceiptBook_Rno > 0 
      AND DeletedFlag = 0 
      AND ReceiptDate BETWEEN @StartDate AND @EndDate;

    -- Box Collection (NU_BoxCollections)
    INSERT INTO #Receipts (Description, Amount, DisplayOrder)
    SELECT 'Box Collection', ISNULL(SUM(Amount), 0), 3
    FROM NU_BoxCollections
    WHERE ConsiderForAudit = 1 
      AND DeletedFlag = 0 
      AND CollectionDate BETWEEN @StartDate AND @EndDate;

    -- Govt Grants (NU_GovtGrants)
    INSERT INTO #Receipts (Description, Amount, DisplayOrder)
    SELECT 'Govt Grants', ISNULL(SUM(Amount), 0), 4
    FROM NU_GovtGrants
    WHERE ConsiderForAudit = 1 
      AND DeletedFlag = 0 
      AND GrantDate BETWEEN @StartDate AND @EndDate;

    -- FD Encashment (Transfer from FD to Bank/Cash during the year)
    INSERT INTO #Receipts (Description, Amount, DisplayOrder)
    SELECT 'Fixed Deposit Encashment', ISNULL(SUM(Amount), 0), 5
    FROM NU_BankTransfers
    WHERE DeletedFlag = 0 
      AND TransferDate BETWEEN @StartDate AND @EndDate
      AND (FromAccountType = 'Fixed Deposit' AND ToAccountType IN ('Cash', 'Bank'))
    HAVING SUM(Amount) > 0;

    -- 2. PAYMENTS
    -- Create temporary table to hold payments
    CREATE TABLE #Payments (
        Description NVARCHAR(100),
        Amount DECIMAL(18,2),
        DisplayOrder INT IDENTITY(1,1)
    );

    -- Payments Grouped by Expense Category
    INSERT INTO #Payments (Description, Amount)
    SELECT ISNULL(c.CategoryName, 'Other Expenses'), SUM(ISNULL(el.Amount, p.DebitAmount))
    FROM NU_Payments p
    LEFT JOIN NU_PaymentExpenseLinks el ON p.PaymentID = el.PaymentId 
              AND ISNULL(el.DeletedFlag, 0) = 0
    LEFT JOIN NU_Categories c ON ISNULL(el.ExpenseCategoryKey, p.ExpenseCategoryId) = c.CategoryId
    WHERE p.DeletedFlag = 0 
      AND p.PaymentDate BETWEEN @StartDate AND @EndDate
    GROUP BY ISNULL(c.CategoryName, 'Other Expenses');

    -- Investment in FD (Transfer from Bank/Cash to FD during the year)
    INSERT INTO #Payments (Description, Amount)
    SELECT 'Investment in Fixed Deposit', ISNULL(SUM(Amount), 0)
    FROM NU_BankTransfers
    WHERE DeletedFlag = 0 
      AND TransferDate BETWEEN @StartDate AND @EndDate
      AND (FromAccountType IN ('Cash', 'Bank') AND ToAccountType = 'Fixed Deposit')
    HAVING SUM(Amount) > 0;

    -- Calculate Totals
    DECLARE @TotalReceipts DECIMAL(18,2) = (SELECT ISNULL(SUM(Amount), 0) FROM #Receipts);
    DECLARE @TotalPayments DECIMAL(18,2) = (SELECT ISNULL(SUM(Amount), 0) FROM #Payments);
    DECLARE @ClosingBalance DECIMAL(18,2) = @TotalReceipts - @TotalPayments;

    -- Add Closing Balance to Payments side
    INSERT INTO #Payments (Description, Amount)
    VALUES ('Closing Balance', @ClosingBalance);

    -- Return 1: Receipts
    SELECT Description, Amount FROM #Receipts ORDER BY DisplayOrder;

    -- Return 2: Payments
    SELECT Description, Amount FROM #Payments ORDER BY DisplayOrder;

    -- Return 3: Summary Totals
    SELECT 
        @TotalReceipts AS TotalReceipts, 
        @TotalPayments AS TotalPayments, -- without closing balance
        @ClosingBalance AS ClosingBalance,
        @TotalReceipts AS FinalTotal -- Both sides tally
        
    DROP TABLE #Receipts;
    DROP TABLE #Payments;
END

GO
