/****** Object:  StoredProcedure [dbo].[NU_UserLogin]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE	[dbo].[NU_UserLogin]
(
	@UserKey	INT = 0,
	@JsonText	NVARCHAR(MAX) = '{"UserID":"roshan","PIN":"1234"}'
)
AS
BEGIN
DECLARE @UserID	VARCHAR(50), @PIN VARCHAR(50), @JSONResult NVARCHAR(MAX)
 
SELECT  @UserID = UserID, @PIN = PIN
from OpenJson(@JsonText, '$')
	With (
		UserID			VARCHAR(50)		'$.UserID',
		PIN				VARCHAR(50)		'$.PIN'
		)

DECLARE @IsLogin BIT = 0
	
SELECT		@IsLogin = CASE WHEN COUNT(*) = 0 THEN 0 ELSE 1 END
FROM		NU_UserDetails
WHERE		UserID = @UserID AND PIN = @PIN

SET @JSONResult = (SELECT @IsLogin AS IsLogin, 1 as LoginKey, CAST(1 AS BIT) AS IsFilterDisplay 
					, CAST(1 AS BIT) AS IsAmountDisplay,   CAST(1 AS BIT) AS IsCountDisplay
					FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)
			
SELECT @JSONResult AS JsonResult


END
