/****** Object:  StoredProcedure [NUAdmin].[NU_DonorYearCalc]    Script Date: 17-09-2026 00:14:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [NUAdmin].[NU_DonorYearCalc]
AS
-- Drop table #Data
SELECT DISTINCT  GM.*,Amount,DonorKey, Year(EventDate) Year,  IsUdyavarParish
into #Data
FROM NU_EventGroupMaster GM
INNER JOIN NU_VGetEventDetails  ED ON GM.Eventgroupkey = ED.EventGroupKey
INNER JOIN NU_VGetDonorDetails DD ON GM.EventGroupKey = DD.EventGroupKey 

SELECT *, 100 - UdyavarAmtPer FROM (
SELECT *, TotalAmt - UdyavaraAmt DiffAmt, CAST((100 * UdyavaraAmt )/TotalAmt AS DECIMAL(18,2)) UdyavarAmtPer  FROM (
SELECT GM.EventGroupName,  GM.OrderBy, SUM(Amount) TotalAmt, SUM(CASE WHEN IsUdyavarParish = 1 THEN Amount ELSE 0 END) UdyavaraAmt 
FROM NU_EventGroupMaster GM
LEFT JOIN #Data D ON D.EventGroupKey = GM.EventGroupKey 
GROUP BY GM.EventGroupName, GM.OrderBy
) A ) A

SELECT *, 100 - UdyavarAmtPer FROM (
SELECT *, TotalAmt - UdyavaraAmt DiffAmt, CAST((100 * UdyavaraAmt )/TotalAmt AS DECIMAL(18,2)) UdyavarAmtPer  FROM (
SELECT D.Year, SUM(Amount) TotalAmt, SUM(CASE WHEN IsUdyavarParish = 1 THEN Amount ELSE 0 END) UdyavaraAmt 
FROM NU_EventGroupMaster GM
LEFT JOIN #Data D ON D.EventGroupKey = GM.EventGroupKey 
GROUP BY D.Year 
) A ) A

GO
